<script setup lang="ts">const platform = usePlatformApi(); const { role, setRole } = useRole(); const status = ref('all'); const { data: tasks, pending, error, refresh: reload } = await useAsyncData('business-tasks', () => platform.listTasks(true)); const refresh = () => reload(); const visible = computed(() => (tasks.value || []).filter(task => status.value === 'all' || task.status === status.value)); onActivated(refresh); useHead({ title: 'Мои задачи — Мост' });</script>
<template><div class="page"><div class="page-heading"><div><h1>Мои задачи<span class="heading-dot">.</span></h1><p>От первого наброска до команды.</p></div><NuxtLink v-if="role === 'business'" to="/tasks/new" class="button button-primary">Новая задача</NuxtLink></div><template v-if="role === 'business'"><div class="filter-tabs"><button v-for="item in ['all','published','confirmed','draft']" :key="item" :class="{ active: status === item }" @click="status = item">{{ { all:'Все', published:'Опубликованные', confirmed:'Подтверждённые', draft:'Черновики' }[item] }}</button></div><p v-if="pending">Загружаем задачи…</p><p v-else-if="error" class="error-text">Не удалось загрузить задачи. <button @click="refresh">Повторить</button></p><div v-else-if="visible.length" class="task-grid tasks-management"><TaskCard v-for="task in visible" :key="task.id" :task="task" manage /></div><EmptyState v-else title="Задач пока нет" description="Создайте первую задачу." /></template><EmptyState v-else title="Раздел бизнеса" description="Переключитесь в роль бизнеса."><button class="button button-primary" @click="setRole('business')">Перейти в роль бизнеса</button></EmptyState></div></template>
